    def upload_externally_generated_certificate_to_hw(self, device_id, certificate_file_data, private_key_data=None, skip_bundle=False,
                                                      timeout=60):
        return self.hwcertman.upload_externally_generated_certificate_to_hw(device_id=device_id, certificate_file_data=certificate_file_data,
                                                                            private_key_data=private_key_data, skip_bundle=skip_bundle,
                                                                            timeout=timeout)

